<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('marketing');$pageTitle='Campaign Expenses';$activeMenu='campaign-expenses';$errors=[];$campaignId=(int)($_GET['campaign_id']??$_POST['campaign_id']??0);
if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$token=$_GET['token']??'';if(!hash_equals(csrf_token(),$token)){http_response_code(419);exit('Invalid token');}$s=db()->prepare('SELECT campaign_id FROM campaign_expenses WHERE id=?');$s->execute([$id]);$cid=(int)$s->fetchColumn();if($cid){db()->prepare('DELETE FROM campaign_expenses WHERE id=?')->execute([$id]);db()->prepare('UPDATE campaigns SET actual_spending=(SELECT COALESCE(SUM(amount),0) FROM campaign_expenses WHERE campaign_id=?) WHERE id=?')->execute([$cid,$cid]);flash('success','Campaign expense deleted.');}redirect('marketing/expenses.php?campaign_id='.$cid);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$campaignId=(int)$_POST['campaign_id'];$date=$_POST['expense_date'];$desc=trim($_POST['description']);$amount=(float)$_POST['amount'];if(!$campaignId||!valid_date($date)||$desc===''||$amount<=0)$errors[]='Complete all expense fields.';if(!$errors){db()->beginTransaction();try{db()->prepare('INSERT INTO campaign_expenses(campaign_id,expense_date,description,amount,created_by) VALUES(?,?,?,?,?)')->execute([$campaignId,$date,$desc,$amount,current_user()['id']]);db()->prepare('UPDATE campaigns SET actual_spending=(SELECT COALESCE(SUM(amount),0) FROM campaign_expenses WHERE campaign_id=?) WHERE id=?')->execute([$campaignId,$campaignId]);db()->commit();log_activity('CREATE','Campaign Expense','Added campaign expense #'.$campaignId);flash('success','Campaign expense added.');redirect('marketing/expenses.php?campaign_id='.$campaignId);}catch(Throwable $e){db()->rollBack();$errors[]=$e->getMessage();}}}
$campaigns=db()->query('SELECT id,campaign_name,budget,actual_spending FROM campaigns ORDER BY start_date DESC')->fetchAll();$rows=[];if($campaignId){$s=db()->prepare("SELECT ce.*,CONCAT(u.first_name,' ',u.last_name) creator FROM campaign_expenses ce JOIN users u ON u.id=ce.created_by WHERE ce.campaign_id=? ORDER BY ce.expense_date DESC,ce.id DESC");$s->execute([$campaignId]);$rows=$s->fetchAll();}$campaign=array_values(array_filter($campaigns,fn($c)=>(int)$c['id']===$campaignId))[0]??null;require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><h1>Campaign Expenses</h1><p>Record actual marketing spend and compare it with the campaign budget.</p></div></div><?php if($errors):?><div class="alert alert-danger"><?=e(implode(' ',$errors))?></div><?php endif;?><div class="row g-3"><div class="col-lg-4"><div class="card-panel"><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-3"><label class="form-label">Campaign</label><select class="form-select" name="campaign_id" required onchange="location='?campaign_id='+this.value"><option value="">Select campaign</option><?php foreach($campaigns as $c):?><option value="<?=$c['id']?>" <?=$campaignId===$c['id']?'selected':''?>><?=e($c['campaign_name'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Expense Date</label><input class="form-control" type="date" name="expense_date" value="<?=e(date('Y-m-d'))?>"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="description" rows="3"></textarea></div><div class="mb-3"><label class="form-label">Amount</label><input class="form-control" type="number" min=".01" step=".01" name="amount"></div><button class="btn btn-primary w-100" <?=$campaignId?'':'disabled'?>>Add Expense</button></form><?php if($campaign):$pct=$campaign['budget']>0?$campaign['actual_spending']/$campaign['budget']*100:0;?><hr><div class="small text-secondary">Campaign Budget</div><strong><?=money($campaign['budget'])?></strong><div class="small text-secondary mt-3">Actual Spending</div><strong><?=money($campaign['actual_spending'])?></strong><div class="stat-progress mt-2"><span style="width:<?=min(100,$pct)?>%"></span></div><div class="small text-secondary mt-1"><?=number_format($pct,1)?>% utilized</div><?php endif;?></div></div></div><div class="col-lg-8"><div class="card-panel"><div class="card-body"><div class="table-responsive"><table class="table data-table"><thead><tr><th>Date</th><th>Description</th><th>Created By</th><th class="text-end">Amount</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['expense_date'])?></td><td><?=e($r['description'])?></td><td><?=e($r['creator'])?></td><td class="text-end"><?=money($r['amount'])?></td><td><a data-confirm="Delete this campaign expense?" class="btn btn-sm btn-light border text-danger" href="<?=e(url('marketing/expenses.php?delete='.$r['id'].'&token='.csrf_token()))?>"><i class="fa-solid fa-trash"></i></a></td></tr><?php endforeach;?></tbody></table></div></div></div></div></div><?php require ROOT_PATH.'/includes/footer.php';?>
